const GITHUB_TOKEN=localStorage.getItem("github_token"),CACHE_KEY="repo_stats_cache",CACHE_DURATION=36e5;async function fetchRepoStats(t,e){const o=`${t}/${e}`,a=getFromCache(o);if(a)return a;try{const a={Accept:"application/vnd.github.v3+json"};GITHUB_TOKEN&&(a.Authorization=`Bearer ${GITHUB_TOKEN}`);const r=await fetch(`https://api.github.com/repos/${t}/${e}`,{headers:a});if(!r.ok)throw new Error(`Failed to fetch repo: ${r.status}`);const s=(await r.json()).stargazers_count,c=await fetch(`https://api.github.com/repos/${t}/${e}/commits?per_page=1`,{headers:a});if(!c.ok)throw new Error(`Failed to fetch commits: ${c.status}`);const n=c.headers.get("link"),i={stars:s,commits:n?parseInt(n.match(/&page=(\d+)>; rel="last"/)?.[1]||"1"):1};return saveToCache(o,i),i}catch(o){return console.warn(`Could not fetch stats for ${t}/${e}:`,o.message),{stars:"—",commits:"—"}}}function getFromCache(t){try{const e=JSON.parse(localStorage.getItem(CACHE_KEY)||"{}")[t];if(e&&Date.now()-e.timestamp<36e5)return e.data}catch(t){console.error("Cache read error:",t)}return null}function saveToCache(t,e){try{const o=JSON.parse(localStorage.getItem(CACHE_KEY)||"{}");o[t]={data:e,timestamp:Date.now()},localStorage.setItem(CACHE_KEY,JSON.stringify(o))}catch(t){console.error("Cache write error:",t)}}async function updateRepoCards(){const t=document.querySelectorAll(".repo-card");for(const e of t){const t=e.getAttribute("href");if(!t||!t.includes("github.com"))continue;const o=t.match(/github\.com\/([^/]+)\/([^/]+)(?:\/|$)/);if(!o)continue;const[,a,r]=o,s=await fetchRepoStats(a,r),c=e.querySelector(".repo-stats");if(c){const t=c.querySelectorAll(".ph");for(const e of t)"[STARS]"===e.textContent?(e.textContent=s.stars,e.classList.remove("ph")):"[COMMITS]"===e.textContent&&(e.textContent=s.commits,e.classList.remove("ph"))}}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",updateRepoCards):updateRepoCards();